State Machine.Timed state machine:
import time

S_OFF = 0
S_ON = 1
S_PAUSE = 2

state = S_OFF
state_timer = 0

def change_state(new_state):
    global state, state_timer
    state = new_state
    state_timer = time.monotonic()

while True:
    if state == S_OFF:
        if start_trigger:
            change_state(S_ON)
    elif state == S_ON:
        if time.monotonic() - state_timer >= 5.0:
            change_state(S_PAUSE)
    elif state == S_PAUSE:
        if time.monotonic() - state_timer >= 1.0:
            change_state(S_ON)

