DSP Filters.Exponential moving average (EMA):
# alpha: 0.0 (no filter) to 1.0 (heavy filter)
ALPHA = 0.1
ema = None

def ema_update(raw):
    global ema
    if ema is None:
        ema = raw
    else:
        ema = ALPHA * raw + (1.0 - ALPHA) * ema
    return ema

