Data Encoding.CRC-8:
def crc8(data):
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            crc = (crc << 1) ^ 0x31 if crc & 0x80 else crc << 1
            crc &= 0xFF
    return crc

Data Encoding.XOR checksum:
def checksum(data):
    result = 0
    for b in data:
        result ^= b
    return result

