NeoPixel / LED Strip.NeoPixel wheel (rainbow):
def wheel(pos):
    # 0-255 input, returns RGB tuple
    pos = pos % 256
    if pos < 85:
        return (255 - pos * 3, pos * 3, 0)
    if pos < 170:
        pos -= 85
        return (0, 255 - pos * 3, pos * 3)
    pos -= 170
    return (pos * 3, 0, 255 - pos * 3)
